using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace HamTool.Services;

/// <summary>One persistent UI language for the entire WPF visual tree.</summary>
public static class LocalizationService
{
    private static readonly ConditionalWeakTable<DependencyObject, Dictionary<DependencyProperty, string>> OriginalValues = new();
    private static readonly DependencyProperty[] TextProperties =
    [
        Window.TitleProperty, TextBlock.TextProperty, ContentControl.ContentProperty,
        HeaderedContentControl.HeaderProperty, FrameworkElement.ToolTipProperty
    ];

    private static readonly Dictionary<string, Dictionary<string, string>> Dictionaries = BuildDictionaries();

    public static string Normalize(string? language) => Dictionaries.ContainsKey(language ?? "") ? language! : "uk";
    public static string Translate(string key, string? language = null)
    {
        var lang = Normalize(language);
        if (lang == "en") return key;
        return Dictionaries[lang].TryGetValue(key, out var value) ? value : key;
    }

    public static void Apply(Window window, string? language)
    {
        var lang = Normalize(language);
        ApplyNode(window, lang, new HashSet<DependencyObject>(ReferenceEqualityComparer.Instance));
    }

    private static void ApplyNode(DependencyObject node, string language, HashSet<DependencyObject> seen)
    {
        if (!seen.Add(node)) return;
        var originals = OriginalValues.GetOrCreateValue(node);
        foreach (var property in TextProperties)
        {
            if (property != FrameworkElement.ToolTipProperty && !property.OwnerType.IsAssignableFrom(node.GetType())) continue;
            if (property == FrameworkElement.ToolTipProperty && node is not FrameworkElement) continue;
            if (!originals.TryGetValue(property, out var original))
            {
                var current = node.GetValue(property);
                if (current is not string text) continue;
                original = text;
                originals[property] = original;
            }
            if (node is FrameworkElement && property == FrameworkElement.ToolTipProperty)
                node.SetValue(property, Translate(original, language));
            else
                node.SetValue(property, Translate(original, language));
        }
        foreach (var child in LogicalTreeHelper.GetChildren(node).OfType<DependencyObject>()) ApplyNode(child, language, seen);
        if (node is Visual or System.Windows.Media.Media3D.Visual3D)
        {
            for (var i = 0; i < VisualTreeHelper.GetChildrenCount(node); i++)
                ApplyNode(VisualTreeHelper.GetChild(node, i), language, seen);
        }
    }

